                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"m-1\",\"rollNo\":1,\"type\":\"ORIGINAL\","
                                + "\"l\":53,\"a\":0,\"b\":0,\"measuredAt\":\"2026-10-01T08:00:00Z\"}"))
