        String body2 = "{\"requestId\":\"m-1\",\"rollNo\":1,\"type\":\"ORIGINAL\","
                + "\"l\":52,\"a\":1,\"b\":1,\"measuredAt\":\"2026-10-01T08:00:00Z\"}";
        mvc.perform(post("/api/batches/" + id + "/measurements")
